uart_puertos = {}
def uart_configurar_ev3(puerto, baudios, bloque):
    # Pybricks 2.0: UARTDevice usa los pines 5 y 6 del puerto de sensor (3.3 V).
    try:
        dispositivo = UARTDevice(puerto, int(baudios), timeout=0)
    except (OSError, ValueError, TypeError) as error:
        rb_fail(bloque, "No se pudo iniciar UART en %s: %s" % (puerto, error))
    uart_puertos[puerto] = [dispositivo, b"", "", False]  # dispositivo, búfer, último mensaje, mensaje nuevo

uart_puertos = {}
def uart_suma(texto):
    # Checksum: XOR de todos los bytes antes de «*», en hexadecimal (como NMEA).
    suma = 0
    for byte in texto.encode():
        suma ^= byte
    return suma
def uart_valida(linea):
    # «datos*CC»: devuelve los datos si el checksum coincide; sin «*» se acepta igual.
    if "*" not in linea:
        return linea
    datos, suma = linea.rsplit("*", 1)
    try:
        return datos if len(suma.strip()) == 2 and int(suma, 16) == uart_suma(datos) else None
    except ValueError:
        return None
def uart_puerto(puerto, bloque):
    datos = uart_puertos.get(puerto)
    if datos is None:
        rb_fail(bloque, "Configura UART %s al iniciar" % puerto)
    # Lee sin bloquear y guarda la última línea completa recibida.
    while datos[0].waiting():
        recibido = datos[0].read_all()
        if not recibido:
            break
        datos[1] += recibido
    while b"\n" in datos[1]:
        linea, datos[1] = datos[1].split(b"\n", 1)
        try:
            texto = uart_valida(linea.decode().strip())
        except UnicodeError:
            texto = None
        # Las líneas con checksum incorrecto se descartan.
        if texto is not None:
            datos[2] = texto.strip()
            datos[3] = True
    if len(datos[1]) > 512:
        datos[1] = datos[1][-512:]
    return datos
def uart_hay_linea(puerto, bloque):
    datos = uart_puerto(puerto, bloque)
    nueva, datos[3] = datos[3], False
    return nueva

