    partes = uart_partes(puerto, bloque)[1]
    try:
        indice = int(numero) - 1
        valor = float(partes[indice]) if indice >= 0 else 0
        # Sin decimales se muestra como entero: 120 en vez de 120.0.
        return int(valor) if valor == int(valor) else valor
    except (IndexError, ValueError, OverflowError):
        return 0

